// HB1: Talos reads the Chronos `times` + `meta` output (Chronos PR #6, merged as b930c52) without losing a scheduler, a
// row, a due list or a health answer. Every fixture is the REAL CLI's stdout (packages/testkit/fixtures/chronos-0.4/,
// regenerated by its generate.py); nothing here is hand-typed Chronos output except the mutations a test says it makes.
// Item numbers are the ones in HB1-TALOS-TOLERATES.md.
import { readdirSync, readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import {
  CHRONOS_API,
  ChronosHealth,
  type ChronosVerb,
  ChronosVersion,
  parseChronosDue,
  parseChronosOrphans,
  parseChronosSnapshot,
  RunKey,
  ScheduleChange,
  ScheduleGetFrame,
  SchedulesListFrame,
  ScheduleWhen,
  ScheduleWhenEditable,
  scheduleFromChronos,
  TIMES_MIN_GAP_MIN,
  timesGapProblem,
} from '../src/index.ts'

const here = dirname(fileURLToPath(import.meta.url))
const dir = join(here, '..', '..', 'testkit', 'fixtures', 'chronos-0.4')
const files = readdirSync(dir).filter((f) => f.endsWith('.json'))
const load = (f: string): any => JSON.parse(readFileSync(join(dir, `${f}.json`), 'utf8'))
const clone = <T>(x: T): T => JSON.parse(JSON.stringify(x))

function verbOf(name: string): ChronosVerb | null {
  const table: Array<[RegExp, ChronosVerb]> = [
    [/^version/, 'version'],
    [/^snapshot-/, 'snapshot'],
    [/^detail-/, 'detail'],
    [/^validate-/, 'validate'],
    [/^due-session/, 'due_session'],
    [/^claim-/, 'claim'],
    [/^finish-/, 'finish'],
    [/^orphans/, 'orphans'],
    [/^start-/, 'start'],
    [/^probe/, 'probe'],
    [/^health/, 'health'],
  ]
  for (const [re, v] of table) if (re.test(name)) return v
  return null
}

const rowOf = (file: string, id: string) => load(file).schedules.find((s: { id: string }) => s.id === id)

describe('HB1 fixtures: every file the real Chronos 0.4 CLI printed parses with the schema for its verb', () => {
  it('has the fixtures', () => {
    expect(files.filter((f) => f !== 'generate.py').length).toBeGreaterThanOrEqual(25)
  })
  for (const f of files) {
    const name = f.replace(/\.json$/, '')
    it(`${f} maps to a verb and parses`, () => {
      const verb = verbOf(name)
      expect(verb, `no verb mapping for ${f}`).not.toBeNull()
      const raw = load(name)
      const r = CHRONOS_API[verb as ChronosVerb].safeParse(raw)
      // Chronos accepts a 45-minute gap (its floor is 15). Talos's schema for what the owner may write refuses it, which
      // is the point: the adapter turns that into a refusal, see apps/bridge/test/schedules/times.test.ts.
      const talosRefuses = name === 'validate-times-45-minutes'
      expect(r.success, r.success ? '' : JSON.stringify(r.error.issues.slice(0, 3), null, 1)).toBe(!talosRefuses)
    })
  }
})

describe('item 1: version.features', () => {
  it('the real version answer, with `features`, parses (it used to close the whole scheduler)', () => {
    const v = ChronosVersion.safeParse(load('version'))
    expect(v.success).toBe(true)
    expect(load('version').features).toEqual(['times', 'meta'])
  })
  it('keeps the features, and one more unknown key does not break detection', () => {
    const v = ChronosVersion.parse({ ...load('version'), future_key: { a: 1 } })
    expect(v.features).toEqual(['times', 'meta'])
    expect(
      ChronosVersion.parse({ api: 1, chronos: '0.3.0', session_runner: 'talos', approval_required: true }).features,
    ).toBeUndefined()
  })
})

describe('item 2: date_key on rows and detail', () => {
  it('a row with date_key (already on Chronos main) is a readable row', () => {
    const p = parseChronosSnapshot(load('snapshot-times-slot-waiting'))
    if (!p.ok) throw new Error(p.message)
    const digest = p.jobs.find((j) => j.id === 'daily-digest')
    expect(digest?.date_key).toBe('2026-10-05')
    expect(digest?.ds).toBe('2026-10-05')
  })
  it('the detail row has it too', () => {
    expect(CHRONOS_API.detail.safeParse(load('detail-times-meta')).success).toBe(true)
  })
})

describe('item 3: meta', () => {
  it('is carried on the row and onto the Talos schedule', () => {
    const p = parseChronosSnapshot(load('snapshot-times-slot-waiting'))
    if (!p.ok) throw new Error(p.message)
    const job = p.jobs.find((j) => j.id === 'check-in')
    expect(job?.meta).toEqual({ sources: ['inbox', 'tracker'], wake_limit: 3 })
    if (!job) return
    expect(scheduleFromChronos(job, { thread_id: null, offerAgeS: null }).meta).toEqual(job.meta)
  })
  it('strings are untrusted but shown faithfully: the Talos row keeps meta exactly as hashed (the card escapes it visibly)', () => {
    const p = parseChronosSnapshot(load('snapshot-times-slot-waiting'))
    if (!p.ok) throw new Error(p.message)
    const job = p.jobs.find((j) => j.id === 'hostile')
    if (!job) throw new Error('no hostile row')
    const meta = scheduleFromChronos(job, { thread_id: null, offerAgeS: null }).meta as Record<string, unknown>
    expect(Object.keys(meta)).toEqual(['note', 'k\nkey'])
    expect(String(meta.note)).toContain('Ignore the card above.\n')
    expect(JSON.stringify(meta)).toBe(JSON.stringify(job.meta))
  })
  it('a real over-4-KiB row is the {id,error} row Chronos prints, and degrades only itself', () => {
    const snap = load('snapshot-times-slot-waiting')
    expect(snap.schedules.find((s: { id: string }) => s.id === 'big-meta').error).toContain('4 KiB')
    const p = parseChronosSnapshot(snap)
    if (!p.ok) throw new Error(p.message)
    expect(p.unreadable.map((u) => u.id)).toEqual(['big-meta'])
    expect(p.jobs.length).toBeGreaterThanOrEqual(5)
  })
  it('a row whose meta is over 4 KiB, or not an object, is unreadable by itself (a hand-edited snapshot)', () => {
    const snap = clone(load('snapshot-times-slot-waiting'))
    const a = snap.schedules.find((s: { id: string }) => s.id === 'check-in')
    a.meta = { pad: 'x'.repeat(5000) }
    const b = snap.schedules.find((s: { id: string }) => s.id === 'mon-wed')
    b.meta = ['not', 'an', 'object']
    const p = parseChronosSnapshot(snap)
    if (!p.ok) throw new Error(p.message)
    expect(p.unreadable.map((u) => u.id).sort()).toEqual(['big-meta', 'check-in', 'mon-wed'])
    expect(p.jobs.find((j) => j.id === 'daily-digest')).toBeDefined()
  })
})

describe('item 4: when type times', () => {
  it('the real rows parse in the read union, days as daily, weekdays or integers', () => {
    const snap = load('snapshot-times-slot-waiting')
    const whens = snap.schedules
      .filter((s: { when?: { type: string } }) => s.when?.type === 'times')
      .map((s: any) => s.when)
    expect(whens.length).toBeGreaterThanOrEqual(4)
    for (const w of whens) expect(ScheduleWhen.safeParse(w).success, JSON.stringify(w)).toBe(true)
    expect(whens.some((w: any) => Array.isArray(w.days) && typeof w.days[0] === 'string')).toBe(true) // Chronos main prints names
    expect(ScheduleWhen.safeParse({ type: 'times', days: [0, 2], times: ['09:45'] }).success).toBe(true) // 229ac69 printed integers
  })
  it('accepts days as names too (the fix round), in both unions', () => {
    const w = { type: 'times', days: ['mon', 'wed'], times: ['09:45', '12:15'] }
    expect(ScheduleWhen.safeParse(w).success).toBe(true)
    expect(ScheduleWhenEditable.safeParse(w).success).toBe(true)
    // Chronos takes daily, weekdays or names; integers are something it once printed, not something to write
    expect(ScheduleWhenEditable.safeParse({ ...w, days: [0, 2] }).success).toBe(false)
    expect(ScheduleWhen.safeParse({ ...w, days: [0, 2] }).success).toBe(true)
  })
  it('an unknown day word degrades the read of that row only, it is not an editable value', () => {
    expect(ScheduleWhen.safeParse({ type: 'times', days: ['someday'], times: ['09:45'] }).success).toBe(true)
    expect(ScheduleWhenEditable.safeParse({ type: 'times', days: ['someday'], times: ['09:45'] }).success).toBe(false)
  })
  it('the normalized change Chronos prints for a times create parses (days are names now, integers in the first PR commits)', () => {
    expect(CHRONOS_API.validate.safeParse(load('validate-times-named-days')).success).toBe(true)
    expect(CHRONOS_API.validate.safeParse(load('validate-times-create')).success).toBe(true)
  })
})

describe('item 5: RunKey wherever a ds appears', () => {
  it('matches a date and a slot, nothing else', () => {
    for (const ok of ['2026-10-05', '2026-10-05T0945', '2026-10-05T1001'])
      expect(RunKey.safeParse(ok).success, ok).toBe(true)
    for (const bad of ['2026-10-05T09:45', '2026-10-05T094', '2026-10-5', '', 'T0945', '2026-10-05T0945Z'])
      expect(RunKey.safeParse(bad).success, bad).toBe(false)
  })
  it('row ds and date_key, last_run.ds, detail runs[].ds', () => {
    const p = parseChronosSnapshot(load('snapshot-times-after-runs'))
    if (!p.ok) throw new Error(p.message)
    const checkIn = p.jobs.find((j) => j.id === 'check-in')
    expect(checkIn?.ds).toBe('2026-10-05T1445')
    expect(checkIn?.last_run?.ds).toBe('2026-10-05T1215')
    const d = CHRONOS_API.detail.parse(load('detail-times-bare-runs'))
    expect((d as any).runs.map((r: any) => r.ds)).toEqual(['2026-10-05T1215', '2026-10-05T0945'])
  })
  it('claim ok.ds, start ok.ds', () => {
    expect(CHRONOS_API.claim.parse(load('claim-times-slot'))).toMatchObject({ ok: true, ds: '2026-10-05T1445' })
    expect(CHRONOS_API.start.parse(load('start-times-headless'))).toMatchObject({ ok: true, ds: '2026-10-05T0950' })
  })
  it('due[].ds: the list reads item by item, so one unreadable slot costs one item', () => {
    const real = parseChronosDue(load('due-session-times'))
    if (!real.ok) throw new Error(real.message)
    expect(real.due.map((d) => d.ds)).toEqual(['2026-10-05T1445'])
    const mixed = clone(load('due-session-times'))
    mixed.due.push({ ...mixed.due[0], ds: '2026-10-05 14:45' }, { ...mixed.due[0], ds: '2026-10-05T1715', id: 'other' })
    const p = parseChronosDue(mixed)
    if (!p.ok) throw new Error(p.message)
    expect(p.due.map((d) => d.ds)).toEqual(['2026-10-05T1445', '2026-10-05T1715'])
    expect(p.bad).toHaveLength(1)
    expect(p.bad[0]).toContain('due[1]')
  })
  it('orphans[].ds reads item by item', () => {
    const real = parseChronosOrphans(load('orphans-times'))
    if (!real.ok) throw new Error(real.message)
    expect(real.orphans.map((o) => o.ds)).toEqual(['2026-10-05T1445'])
    const mixed = clone(load('orphans-times'))
    mixed.orphans.push({ id: 'x-job', ds: 'tuesday', run_id: mixed.orphans[0].run_id })
    const p = parseChronosOrphans(mixed)
    if (!p.ok) throw new Error(p.message)
    expect(p.orphans).toHaveLength(1)
    expect(p.bad).toHaveLength(1)
  })
  it('probe stalled_in_window[].ds, and health blocked.ds: a stalled slot no longer fails the whole answer', () => {
    expect(CHRONOS_API.probe.parse(load('probe-times-stalled-in-window'))).toMatchObject({
      stalled_in_window: [{ id: 'mon-wed', ds: '2026-10-05T1215' }],
    })
    const h = load('health-times-blocked-slot')
    expect(h.blocked.ds).toBe('2026-10-05T1215')
    expect(ChronosHealth.safeParse(h).success).toBe(true)
    const odd = clone(h)
    odd.blocked.ds = 'some-new-format'
    odd.issues.push({ code: 'launch_stalled', schedule_id: 'Not A Valid Id' })
    const r = ChronosHealth.safeParse(odd)
    expect(r.success, r.success ? '' : JSON.stringify(r.error.issues)).toBe(true)
    expect(r.success && r.data.blocked?.ds).toBeNull()
    expect(r.success && r.data.issues.at(-1)?.schedule_id).toBeNull()
  })
})

describe('items 6-10: the shapes that flip', () => {
  it('6: Run now on a times job returns an ad-hoc minute key; it parses and is just a key', () => {
    for (const f of ['claim-times-run-now-adhoc', 'claim-times-run-now-adhoc-slotshaped']) {
      const c = CHRONOS_API.claim.parse(load(f)) as { ok: true; ds: string }
      expect(c.ds).toMatch(/^2026-10-05T\d{4}$/)
    }
    // 10:01 is in no job's slot list (09:45 12:15 14:45 17:15)
    expect((CHRONOS_API.claim.parse(load('claim-times-run-now-adhoc')) as { ds: string }).ds).toBe('2026-10-05T1001')
    expect(rowOf('snapshot-times-slot-waiting', 'check-in').when.times).not.toContain('10:01')
  })
  it('7: the same times job reads with a slot ds on a work day and a plain date on the weekend', () => {
    const work = rowOf('snapshot-times-slot-waiting', 'check-in')
    const weekend = rowOf('snapshot-times-weekend', 'check-in')
    expect(work.ds).toBe('2026-10-05T0945')
    expect(weekend.ds).toBe('2026-10-10')
    expect(weekend.date_key).toBe('2026-10-10')
    for (const f of ['snapshot-times-slot-waiting', 'snapshot-times-weekend']) {
      const p = parseChronosSnapshot(load(f))
      expect(p.ok && p.jobs.some((j) => j.id === 'check-in')).toBe(true)
    }
    expect(CHRONOS_API.detail.safeParse(load('detail-times-weekend')).success).toBe(true)
  })
  it('8: a plain-time job carries slot-key last_run and runs after a switch from times', () => {
    const swapped = rowOf('snapshot-times-after-runs', 'swapped')
    expect(swapped.when.type).toBe('daily')
    expect(swapped.last_run.ds).toBe('2026-10-05T0945')
    const p = parseChronosSnapshot(load('snapshot-times-after-runs'))
    expect(p.ok && p.jobs.find((j) => j.id === 'swapped')?.last_run?.ds).toBe('2026-10-05T0945')
    const d = CHRONOS_API.detail.parse(load('detail-switched-to-plain')) as any
    expect(d.runs[0].ds).toBe('2026-10-05T0945')
  })
  it("9: today='missed' on a slot key, and claim reason window_passed, need no new enum value", () => {
    const missed = rowOf('snapshot-times-missed-superseded', 'check-in')
    expect(missed.today).toBe('missed')
    expect(missed.ds).toBe('2026-10-05T1715')
    const p = parseChronosSnapshot(load('snapshot-times-missed-superseded'))
    expect(p.ok && p.jobs.find((j) => j.id === 'check-in')?.today).toBe('missed')
    expect(CHRONOS_API.claim.parse(load('claim-times-window-passed'))).toEqual({ ok: false, reason: 'window_passed' })
  })
  it('10: bare runs keep their nulls on the wire and lose them on the way in, in last_run and in runs[]', () => {
    const raw = load('detail-times-bare-runs')
    expect(raw.runs[0]).toMatchObject({ run_id: null, started_at: null, runner: null })
    const d = CHRONOS_API.detail.parse(raw) as any
    expect(d.runs[0]).toEqual({ ds: '2026-10-05T1215', trigger: 'clock', status: 'failed', has_report: false })
    const after = parseChronosSnapshot(load('snapshot-times-after-runs'))
    if (!after.ok) throw new Error(after.message)
    expect(after.jobs.find((j) => j.id === 'check-in')?.last_run).not.toHaveProperty('run_id')
  })
})

describe('a times job in the app', () => {
  it('arrives read-only: the owner form holds one fire time, and saving a times job through it would make it daily', () => {
    const p = parseChronosSnapshot(load('snapshot-times-slot-waiting'))
    if (!p.ok) throw new Error(p.message)
    const job = p.jobs.find((j) => j.id === 'check-in')
    if (!job) throw new Error('no row')
    expect(job.editable).toBe(true) // Chronos itself would take an edit
    const s = scheduleFromChronos(job, { thread_id: null, offerAgeS: null })
    expect(s.editable).toBe(false)
    expect(s.read_only_reason).toContain('Edit its fire times at the Mac')
    const plain = p.jobs.find((j) => j.id === 'daily-digest')
    if (plain) expect(scheduleFromChronos(plain, { thread_id: null, offerAgeS: null }).editable).toBe(true)
  })
})

describe('one bad row degrades that row only (class 2)', () => {
  it('an unknown when type, a bad ds, a bad date_key, an unknown state: each is one unreadable row', () => {
    const snap = clone(load('snapshot-times-slot-waiting'))
    const by = (id: string) => snap.schedules.find((s: { id: string }) => s.id === id)
    by('check-in').when = { type: 'fortnightly', every: 2 }
    by('mon-wed').ds = '2026-10-05 09:45'
    by('swapped').date_key = 'yesterday'
    by('hostile').today = 'sideways'
    const p = parseChronosSnapshot(snap)
    if (!p.ok) throw new Error(p.message)
    expect(p.unreadable.map((u) => u.id).sort()).toEqual(['big-meta', 'check-in', 'hostile', 'mon-wed', 'swapped'])
    expect(p.jobs.map((j) => j.id)).toEqual(['daily-digest', 'tight'])
  })
  it('an extra key on the version, or an unknown extra key on the snapshot head, does not close the scheduler', () => {
    expect(ChronosVersion.safeParse({ ...load('version'), later: true }).success).toBe(true)
    const snap = { ...clone(load('snapshot-times-slot-waiting')), later_head_key: 1 }
    expect(parseChronosSnapshot(snap).ok).toBe(true)
  })
})

describe('the 60-minute floor (protocol entry: the owner form and the agent both build a ScheduleChange)', () => {
  const create = (times: string[], days: unknown = 'weekdays') => ({
    op: 'create',
    draft: {
      id: 'beat-job',
      name: 'Beat',
      description: '',
      when: { type: 'times', days, times },
      catchup_min: 60,
      enabled: true,
      runner: 'session',
      permissions: 'full',
      allowed_tools: [],
      model: null,
      notify: 'failure',
      thread_id: null,
      prompt: 'Check things.',
    },
  })
  it('the floor is 60', () => {
    expect(TIMES_MIN_GAP_MIN).toBe(60)
  })
  it('rejects a 45-minute gap and says which two times', () => {
    const r = ScheduleChange.safeParse(create(['09:00', '09:45']))
    expect(r.success).toBe(false)
    expect(JSON.stringify(r.error?.issues)).toContain('60 minutes')
    expect(JSON.stringify(r.error?.issues)).toContain('09:00')
  })
  it('accepts exactly 60, and the 15-minute floor of Chronos itself is not enough', () => {
    expect(ScheduleChange.safeParse(create(['09:00', '10:00'])).success).toBe(true)
    expect(ScheduleChange.safeParse(create(['09:00', '09:15'])).success).toBe(false)
  })
  it('counts the gap across midnight (23:30 and 00:15 are 45 apart)', () => {
    expect(ScheduleChange.safeParse(create(['00:15', '23:30'])).success).toBe(false)
    expect(ScheduleChange.safeParse(create(['00:30', '23:30'])).success).toBe(true)
  })
  it('wants them in order, 1 to 12 of them', () => {
    expect(ScheduleChange.safeParse(create(['12:00', '09:00'])).success).toBe(false)
    expect(ScheduleChange.safeParse(create([])).success).toBe(false)
    const thirteen = Array.from({ length: 13 }, (_, i) => `${String(i * 1 + 8).padStart(2, '0')}:00`).filter(
      (t) => t < '24',
    )
    expect(ScheduleChange.safeParse(create(thirteen.slice(0, 13))).success).toBe(false)
  })
  it('an update `set.when` is held to it as well', () => {
    const upd = (times: string[]) => ({
      op: 'update',
      id: 'beat-job',
      base_etag: `sha256:${'a'.repeat(64)}`,
      set: { when: { type: 'times', days: 'daily', times } },
    })
    expect(ScheduleChange.safeParse(upd(['09:00', '09:45'])).success).toBe(false)
    expect(ScheduleChange.safeParse(upd(['09:00', '10:00'])).success).toBe(true)
  })
  it('a job already on the Mac with a 45-minute gap is still READ: the floor is for what the owner writes', () => {
    expect(ScheduleWhen.safeParse({ type: 'times', days: 'weekdays', times: ['09:00', '09:45'] }).success).toBe(true)
    const p = parseChronosSnapshot(load('snapshot-times-slot-waiting'))
    expect(p.ok && p.jobs.find((j) => j.id === 'tight')).toBeTruthy()
  })
  it('timesGapProblem is the one rule', () => {
    expect(timesGapProblem(['09:00', '10:00'])).toBeNull()
    expect(timesGapProblem(['09:00', '09:45'])).toContain('45')
  })
})

describe('R1-3: the app says what it can read, in the signed request', () => {
  it('schedules.list and schedule.get carry an optional app_features, and an old request without it still parses', () => {
    expect(SchedulesListFrame.shape.app_features.safeParse(['schedules/2']).success).toBe(true)
    expect(ScheduleGetFrame.shape.app_features.safeParse(undefined).success).toBe(true)
    expect(SchedulesListFrame.shape.app_features.safeParse(['x'.repeat(41)]).success).toBe(false)
  })
})
